window.MegaMenu = {};

window.MegaMenu.helpers = (function(){
    var self = {};

    self.random = function(length) {
        return Math.random().toString(36).substr(2, ( length && length <=12 ) ? length : 12);
    };

    return self;
})();

/**
 * Mega menu, it has dependency on Jquery, should load after Jquery
 */
window.MegaMenu.service = (function(){

    var self = {};

    var _data = {
        focusingButton: {},
        focusingPanel: {}
    };

    var _subscribers = [];
    var _buttonStateTimeOut = undefined;
    var _panelStateTimeOut = undefined;


    /*---------------------------- public functions state handlers -------------------------*/
    self.resetButtonState = function() {
        _buttonStateTimeOut = window.setTimeout(function(){
            delete _data.focusingButton.id;
            self.broadcastDataChanges("focusingButton");
        }, 500);
    };

    self.resetFlyOutPanelState = function() {
        _panelStateTimeOut = window.setTimeout(function(){
            delete _data.focusingPanel.id;
            self.broadcastDataChanges("focusingPanel");
        }, 500);
    };

    self.setFocusingButton = function(id) {
        window.clearTimeout(_buttonStateTimeOut);
        window.clearTimeout(_panelStateTimeOut);
        _data.focusingButton.id = id;
        self.broadcastDataChanges("focusingButton");
    };

    self.setFocusingPanel = function(id) {
        window.clearTimeout(_panelStateTimeOut);
        window.clearTimeout(_buttonStateTimeOut);
        _data.focusingPanel.id = id;
        self.broadcastDataChanges("focusingPanel");
    };



    /*---------------------------- public functions -------------------------*/
    /**
     * Subscribe changes
     * @param keyPath
     * @param handler
     * @param instance
     * @returns {{id: *, key: *, proxy: *, fn: *}}
     */
    self.subscribe = function(keyPath, handler, instance) {

        if( keyPath === undefined ) {
            throw new Error('keyPath is required to subscribe data service');
        }
        if( handler === undefined ) {
            throw new Error('fn is required to subscribe data service');
        }
        const subscriber = {
            instance: instance,
            id: window.MegaMenu.helpers.random(6),
            keyPath: keyPath,
            handler: handler,
            data: _data[keyPath]
        };
        _subscribers.push(subscriber);
        return subscriber;
    };


    /**
     * Notify all subscribers data object changes
     * Use it after loading the data from the server.
     * @param {String} keyPath - key path of the this._data
     * @param {Object} excluded - subscriber, excluded subscriber
     * @example
     * ```
     * this._data.currentSite = {name: "corporate"};
     * //subscribers listen to the currentSite changes
     *
     * this.broadcastDataChanges("currentSite");
     * //tell all subscribers "currentSite" which has changed
     *
     * ```
     *
     * An example `/src/components/style-guide/style-guide-service.js`
     *
     * @private
     */
    self.broadcastDataChanges = function(keyPath, excluded) {
        var data = _data[keyPath];

        _subscribers.forEach(function(subscriber){
            if(subscriber !== undefined &&
                subscriber.keyPath === keyPath &&
                excluded !== subscriber) {
                    subscriber.handler(keyPath, data);
            }
        });
    };

    return self;
})();


window.MegaMenu.items = [];

window.MegaMenu.createItem = function($el) {

    var self = {};
    var FlyOutMenuService = window.MegaMenu.service;


    function init($el){
        self.$el = $el;
        self.id = window.MegaMenu.helpers.random(12);

        var subscriberFocusingButton = window.MegaMenu.service.subscribe('focusingButton', self.handleFocusingButtonChange, self.id);
        var subscriberFocusingPanel = window.MegaMenu.service.subscribe('focusingPanel', self.handleFocusingPanelChange, self.id);

        self._data = {
            buttonId: self.id + "_button",
            panelId: self.id + "_panel",
            focusingButton:  subscriberFocusingButton.data,
            focusingPanel: subscriberFocusingPanel.data
        };

        self.$button = self.$el.find('[data-js-el="button"]');
        self.$panel = self.$el.find('[data-js-el="panel"]');

        //Add id attr, so tab-collapser.js is able to catch the button id.
        //Another approach is to use get and set in FlyOutMenuService, but using attribute here is easier.
        self.$button.attr('data-js-id', self._data.buttonId);
        self.$panel.attr('data-js-id', self._data.panelId);

        //Link button focus and blur handlers
        self.$button.mouseover(self.onFocusButton);
        self.$button.focus(self.onFocusButton);
        self.$button.blur(self.onBlurButton);
        self.$button.mouseout(self.onBlurButton);
        //Link button touch screen event handler

        self.$button[0].addEventListener('touchstart', self.onTouchStart);

        //Panel focus and blur event handlers
        self.$panel.mouseover(self.onFocusPanel);
        self.$panel.focus(self.onFocusPanel);
        self.$panel.blur(self.onBlurPanel);
        self.$panel.mouseout(self.onBlurPanel);

        //Create dropdown panel links focus and blur events for the touch screen
        self.$panel.find('a').each(function(index, panelButton){
            $(panelButton).focus(self.onFocusPanel);
            $(panelButton).blur(self.onBlurPanel);
        });

        //Create body touch event handler when touch outside of the panel or nav buttons
        document.addEventListener('touchstart', this.onTouchBody);

        window.MegaMenu.items.push(self);
    }



    /*---------------------------- notification handlers ----------------------------*/
    self.handleFocusingButtonChange = function(keyPath, data) {
        if(self._data.buttonId === data.id){
            self.$panel.show();
        } else {
            self.$panel.hide();
        }
    };

    self.handleFocusingPanelChange = function(keyPath, data) {
        if(self._data.panelId !== data.id){
            self.$panel.hide();
        }
    };



    /*---------------------------- view handlers ----------------------------*/
    self.onTouchStart = function(e) {
        if (self._data.buttonId !== self._data.focusingButton.id) {
            e.stopPropagation();
            e.preventDefault();
            this.onFocusButton();
        }
    };

    self.onTouchBody = function() {
        FlyOutMenuService.resetButtonState();
        FlyOutMenuService.resetFlyOutPanelState();
    };

    self.onFocusButton = function() {
        FlyOutMenuService.setFocusingButton(self._data.buttonId);
    };

    self.onBlurButton = function() {
        FlyOutMenuService.resetButtonState();
    };

    self.onFocusPanel = function() {
        FlyOutMenuService.setFocusingPanel(self._data.panelId);
    };

    self.onBlurPanel = function() {
        FlyOutMenuService.resetFlyOutPanelState();
    };


    init($el);

    return self;

};

/**
 * Bind dynamic content 
 */
window.MegaMenu.bindContent = function($container) {
    $container = $container || $('body');
    var items = $container.find('.b-js-fly-out-menu-item');

    if(window.location.href.includes('student')) //FIXME:- Workaround for disabling fly over menu on students page.
        return;
    if(items.length > 0) {
        items.each(function(index, item){
            window.MegaMenu.createItem($(item));
        })
    }
};


/**
 * run with add item
 */
(function(){
    window.MegaMenu.bindContent();
})();


