function mazeMapInitialize(mapDivId, options) {
    var myMap = new Mazemap.Map({
        container: mapDivId,
        campuses: "unisyd",
        center: { lng: options.longitude, lat: options.latitude },
        zoom: options.zoomLevel,
        zLevel:options.zlevel,
        scrollZoom: true,
        doubleClickZoom: true,
        touchZoomRotate: true,
        zLevelControl: true,
        zLevelUpdater: true,
    });
    myMap.addControl(new Mazemap.mapboxgl.NavigationControl());
    myMap.on("load", function () {
        // MazeMap ready
        var lngLat = myMap.getCenter();

        var marker = new Mazemap.MazeMarker({
            color: "MazeBlue",
            size: 36,
            speed: 0.5,
        })
            .setLngLat(lngLat)
            .addTo(myMap);
    });
}

